package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.mapper.OwnerMapper;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

public class BuildOwner {

    public void service(@Val OwnerFieldsDto request, OwnerMapper ownerMapper, Out<Owner> built) {
        Owner owner = ownerMapper.toOwner(request);
        // When no registration date is supplied, default it to the server's current date.
        if (owner.getRegistrationDate() == null) {
            owner.setRegistrationDate(LocalDate.now());
        }
        built.set(owner);
    }
}
=== CheckOwnerHouseholdUnique ===
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Rejects a create request whose last name and address, normalized, already belong to another owner.
 *
 * <p>Runs after {@link ValidateOwnerFields} and before {@link BuildOwner}. Both the request and
 * every stored owner's last name and address are reduced through {@link OwnerHousehold#normalize}
 * (case-insensitive, whitespace collapsed) before comparison, so differently cased or spaced values
 * that mean the same thing still collide. A match throws {@link OwnerHouseholdDuplicateException},
 * handled as a 409 Conflict — unless the request opted in with {@code sharesHousehold: true}, which
 * permits owners who genuinely share a household.
 */
public class CheckOwnerHouseholdUnique {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws OwnerHouseholdDuplicateException {
        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
            return;
        }
        for (Owner existing : ownerRepository.findAll()) {
            if (OwnerHousehold.sameHousehold(existing, request.getLastName(),
                    request.getAddress())) {
                throw new OwnerHouseholdDuplicateException(request.getLastName(),
                        request.getAddress());
            }
        }
    }
}
=== CheckOwnerTelephoneUnique ===
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Rejects a create request whose normalized telephone is already used by any other owner.
 *
 * <p>Runs after {@link ValidateOwnerFields} and before {@link BuildOwner}. Both the request and
 * every stored owner's telephone are reduced to E.164 through the shared
 * {@link OwnerTelephone#toE164} rule before comparison, so differently formatted numbers that
 * collapse to the same E.164 value still collide. A match throws
 * {@link OwnerTelephoneInUseException}, handled as a 409 Conflict.
 */
public class CheckOwnerTelephoneUnique {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws OwnerTelephoneInUseException {
        String telephone = OwnerTelephone.toE164(request.getTelephone());
        if (telephone == null) {
            return;
        }
        for (Owner existing : ownerRepository.findAll()) {
            if (telephone.equals(OwnerTelephone.toE164(existing.getTelephone()))) {
                throw new OwnerTelephoneInUseException(request.getTelephone());
            }
        }
    }
}
=== ValidateOwnerFields ===
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.ArrayList;
import java.util.List;

import net.officefloor.plugin.variable.Out;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * Rejects a create request that is missing or blank in any required owner field.
 *
 * <p>Runs first in the {@code POST /api/owners} pipeline. It binds the body once (this is the only
 * step that reads {@code @RequestBody}) and republishes it for {@link BuildOwner}. Each of
 * firstName, lastName, address, city and telephone must be present and non-blank; any that are not
 * are collected and reported together via {@link OwnerFieldsInvalidException}.
 *
 * <p>The telephone is converted to E.164 form (see {@link OwnerTelephone#toE164}). The E.164 value
 * replaces the submitted one on the republished body, so it is what gets stored and returned. A
 * number that cannot form valid E.164 is rejected as an invalid {@code telephone}.
 */
public class ValidateOwnerFields {

    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
            throws OwnerFieldsInvalidException {
        List<String> errors = new ArrayList<>();
        if (isBlank(request.getFirstName())) {
            errors.add("firstName");
        }
        if (isBlank(request.getLastName())) {
            errors.add("lastName");
        }
        // The address is normalized (whitespace collapsed, upper-cased, abbreviations expanded)
        // before the required-field check, so an address that is blank only after normalization is
        // rejected; the normalized value replaces the submitted one, so it is what gets stored,
        // returned and compared for household identity.
        String address = OwnerAddress.normalize(request.getAddress());
        if (address.isEmpty()) {
            errors.add("address");
        }
        else {
            request.setAddress(address);
        }
        if (isBlank(request.getCity())) {
            errors.add("city");
        }
        if (isBlank(request.getTelephone())) {
            errors.add("telephone");
        }
        else {
            String telephone = OwnerTelephone.toE164(request.getTelephone());
            if (telephone == null) {
                errors.add("telephone");
            }
            else {
                request.setTelephone(telephone);
            }
        }
        // Email is optional. When present it must be syntactically valid; it is normalized to
        // lower case so it is stored and returned lower-cased.
        String email = request.getEmail();
        if (email != null) {
            if (!OwnerEmail.isValid(email)) {
                errors.add("email");
            }
            else {
                request.setEmail(OwnerEmail.normalize(email));
            }
        }
        if (!errors.isEmpty()) {
            throw new OwnerFieldsInvalidException(errors);
        }
        validated.set(request);
    }

    private static boolean isBlank(String value) {
        return value == null || value.isBlank();
    }
}
